  /* Version 26: Kurzform in Objekte umwandeln. Höhenmeter, wo nicht angegeben, aus dem Charakter geschätzt
     (Rad flach 3 · wellig 7 · hügelig 12 · bergig 22 m je km; Laufen 1 · 3 · 6 · 12 m je km). */
  const HM_KM = { flach: [3, 1], wellig: [7, 3], huegelig: [12, 6], bergig: [22, 12] };
  const art = (tags) => ['bergig', 'huegelig', 'wellig', 'flach'].find((t) => tags.includes(t)) || 'wellig';
  const zehn = (x) => Math.round(x / 10) * 10;
  LAUF.forEach(([id, name, serie, ort, land, lat, lon, mon, hmLauf, n, tg, note, url, x]) => {
    const tags = tg.split(' '), L0 = serie === 'ul' ? (x && x.laufKm) || 50 : SERIE[serie].lauf;
    R.push(Object.assign({ id, name, serie, ort, land, lat, lon, mon, n: n || 0, tags, note, url: url || '', hmLauf: hmLauf != null ? hmLauf : zehn(L0 * HM_KM[art(tags)][1]), kurz: true }, x || {}, { geschaetzt: !(x && x.hmOk) }));
  });
  TRI.forEach(([id, name, serie, ort, land, lat, lon, mon, swim, n, tg, note, url, x]) => {
    const tags = tg.split(' '), S0 = SERIE[serie], k = (x && x.km && x.km[S0.dist]) || [S0.swim, S0.rad, S0.lauf], f = HM_KM[art(tags)];
    R.push(Object.assign({ id, name, serie, ort, land, lat, lon, mon, swim: swim || null, n: n || 0, tags, note, url: url || '', hmRad: zehn(k[1] * f[0]), hmLauf: zehn(k[2] * f[1]), kurz: true }, x || {}, { geschaetzt: !(x && x.hmOk) }));
  });

